1089			}
1090			return cluster, nil
1091		} else if destination.Name != "" {
1092			clusterURLs, err := db.GetClusterServersByName(ctx, destination.Name)
1093			if err != nil {
1094				return nil, fmt.Errorf("error getting cluster by name %q: %w", destination.Name, err)
1095			}
1096			if len(clusterURLs) == 0 {
1097				return nil, fmt.Errorf("there are no clusters with this name: %s", destination.Name)
1098			}
1099			if len(clusterURLs) > 1 {
1100				return nil, fmt.Errorf("there are %d clusters with the same name: [%s]", len(clusterURLs), strings.Join(clusterURLs, " "))
