29	// ClusterInformer provides a cached view of cluster secrets as Cluster objects.
30	// It uses an informer with a transform function to convert Secret -> Cluster
31	// once during ingestion, avoiding repeated conversions.
32	//
33	// This eliminates the performance cost of calling SecretToCluster on every
34	// GetCluster/GetClusterServersByName call, which can be significant in hot paths.
35	type ClusterInformer struct {
36		cache.SharedIndexInformer
37	}
38	
39	// NewClusterInformer creates a new cluster cache that watches cluster secrets
40	// and stores them as pre-converted Cluster objects using informer transforms.
41	//
42	// The transform function runs once per secret during informer ingestion,
43	// converting Secret -> Cluster at that time. This means:
44	// - Zero conversion overhead on reads (already converted)
45	// - Same freshness guarantees as regular informers
46	// - Automatic updates when secrets change
47	func NewClusterInformer(clientset kubernetes.Interface, namespace string) (*ClusterInformer, error) {
48		informer := informersv1.NewFilteredSecretInformer(clientset, namespace, 3*time.Minute, cache.Indexers{
49			cache.NamespaceIndex: cache.MetaNamespaceIndexFunc,
50			ClusterCacheByURLIndexer: func(obj any) ([]string, error) {
51				cluster, ok := obj.(*appv1.Cluster)
52				if !ok {
53					return nil, nil
