// getUpdatedClusterInfo sets the number of applications assigned to the cluster
// on the provided clusterInfo and returns it. An application is counted when its
// destination server URL matches the cluster's server URL, or when its
// destination name resolves via a database lookup to the cluster's server URL.
// If a destination name is ambiguous (it resolves to more than one server URL),
// applications targeting the cluster by that name are not counted.
func (c *clusterInfoUpdater) getUpdatedClusterInfo(ctx context.Context, apps []*appv1.Application, cluster appv1.Cluster, clusterInfo *appv1.ClusterInfo, now metav1.Time) *appv1.ClusterInfo {
	var appCount int64
	for _, a := range apps {
		if c.projGetter != nil {
			proj, err := c.projGetter(a)
			if err != nil || !proj.IsAppNamespacePermitted(a, c.namespace) {
				continue
			}
		}
		dest := a.Spec.Destination
		switch {
		case dest.Server != "":
			if dest.Server == cluster.Server {
				appCount++
			}
		case dest.Name != "":
			servers, err := c.db.GetClusterServersByName(ctx, dest.Name)
			if err != nil {
				continue
			}
			// Skip ambiguous names that resolve to more than one server URL.
			if len(servers) == 1 && servers[0] == cluster.Server {
